===== OwnerIdentity =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code identityKey}: the one derived value that all
 * create-time duplicate detection for {@code POST /owners} is expressed through. It consolidates
 * what used to be several separate guards (telephone, email and household) into a single key, so a
 * request is a duplicate only when its <em>whole</em> key equals an existing owner's.
 *
 * <p>The key is the lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
 * soundex(lastName)}:
 * <ul>
 *   <li>telephone is canonicalised to E.164 ({@link OwnerTelephone#toE164OrRaw(String)}) so the
 *       comparison is independent of how a value happens to be formatted;</li>
 *   <li>email is the stored lower-cased form ({@link OwnerEmail#normalize(String)}) when present,
 *       otherwise the empty string (email is optional);</li>
 *   <li>last name contributes its Soundex code ({@link OwnerSoundex#of(String)}), so surnames that
 *       sound alike share that component.</li>
 * </ul>
 *
 * <p>Because the telephone is part of the key, two owners with the same last name and postcode but
 * different telephones have different keys and are both allowed (the later pipeline flags the second
 * as a <em>possible</em> duplicate, see {@link AssignPossibleDuplicate}); only an exact full-key
 * match counts as a duplicate.
 *
 * <p>Centralised here so {@link CheckOwnerIdentityUnique} (which rejects collisions) and the owner
 * mapper (which returns the key) cannot disagree on how it is derived.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The identity key of an existing owner, derived from its stored fields. */
    public static String of(Owner owner) {
        return key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
    }

    /**
     * The identity key for the given parts: the lower-case hex SHA-256 of
     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
     */
    public static String key(String telephone, String email, String lastName) {
        String raw = OwnerTelephone.toE164OrRaw(telephone) + "|" + normalizeEmail(email) + "|"
                + OwnerSoundex.of(lastName);
        return Sha256.hex(raw);
    }

    private static String normalizeEmail(String email) {
        return OwnerEmail.isPresent(email) ? OwnerEmail.normalize(email) : "";
    }
}
===== OwnerLocality =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Single source of truth for the owner locality rule shared across the {@code POST /owners}
 * pipeline. The region is derived from the <em>postcode range</em> first (NSW 2000-2099,
 * VIC 3000-3099, QLD 4000-4099), falling back to a fixed city-to-region table
 * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) only when the postcode is absent or in no
 * known range; any other input has no known region. Resolving by postcode first returns the same
 * region for the known cities but disambiguates cities that share a name.
 *
 * <p>Centralised here (as {@link OwnerAddress} is for address normalisation) so the read-time and
 * write-time sides of the rule cannot drift: {@code OwnerMapper.locality} derives the returned
 * {@code locality} from it, and {@link ValidateOwnerPostcode} uses it to decide which region's
 * postcode range a supplied postcode must fall within.
 */
public final class OwnerLocality {

    /** City -> canonical region. Anything not listed has no known region. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    /** Region -> IANA timezone name. Anything not listed has no known timezone. */
    private static final Map<String, String> REGION_TIMEZONE = Map.of(
            "NSW", "Australia/Sydney",
            "VIC", "Australia/Melbourne",
            "QLD", "Australia/Brisbane");

    private OwnerLocality() {
    }

    /**
     * The canonical region for the given city, or {@code null} when the city is not in the
     * table (no known region).
     */
    public static String regionForCity(String city) {
        return city == null ? null : CITY_REGION.get(city);
    }

    /**
     * The canonical region whose postcode range contains the given postcode, or {@code null} when
     * the postcode is absent, not four digits, or in no known range.
     */
    public static String regionForPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /** The region's inclusive 4-digit postcode range {low, high}, or {@code null} when none. */
    public static int[] postcodeRange(String region) {
        return region == null ? null : REGION_POSTCODES.get(region);
    }

    /** Whether the region is one of the known regions (NSW, VIC, QLD). */
    public static boolean isKnownRegion(String region) {
        return region != null && REGION_POSTCODES.containsKey(region);
    }

    /**
     * The region's IANA timezone name (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
     * QLD-&gt;Australia/Brisbane), or {@code null} when the region is null or has no known timezone.
     */
    public static String timezoneForRegion(String region) {
        return region == null ? null : REGION_TIMEZONE.get(region);
    }

    /**
     * The owner's canonical region, preferring the postcode's region and falling back to the
     * city-to-region table when the postcode is absent or in no known range. Returns {@code null}
     * when neither yields a known region. Callers that need a display sentinel map {@code null}
     * themselves (e.g. to {@code "UNKNOWN"}).
     */
    public static String regionFor(String postcode, String city) {
        String region = regionForPostcode(postcode);
        return region != null ? region : regionForCity(city);
    }
}
===== OwnerMemberId =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code memberId}: the one unified identity every other
 * derived owner value flows from. It owns both sides of the {@code <REGION><FY><HASH8><CHK>} format
 * so the write-time side ({@link AssignMemberId}, which constructs it) and the read-time side
 * ({@code OwnerMapper.locality}, which recovers the region from it) cannot drift — mirroring how
 * {@link OwnerIdentity}, {@link OwnerTelephone} and {@link OwnerLocality} centralise their rules.
 *
 * <p>The format is {@code <REGION><FY><HASH8><CHK>} (e.g. {@code NSW271A2B3C4D5}) where:
 * <ul>
 *   <li>{@code REGION} is the owner's region ({@link #regionFor}): the postcode's region, falling
 *       back to the city-to-region table, and {@link #UNKNOWN_REGION} when neither resolves;</li>
 *   <li>{@code FY} is the two-digit fiscal year (starting 1 July) that contains the
 *       business-day-adjusted {@code registrationDate}, derived via {@link FiscalYear#yy} — the
 *       single source of truth shared with the read-time {@code fiscalYear} label;</li>
 *   <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the owner's
 *       canonical telephone ({@link OwnerTelephone#toE164OrRaw(String)}) concatenated with its
 *       last name — the same region-and-hash identity {@code HASH8};</li>
 *   <li>{@code CHK} is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}.</li>
 * </ul>
 *
 * <p>{@code REGION} is a fixed set of letters ({@code NSW}/{@code VIC}/{@code QLD}/{@code UNKNOWN})
 * and the segments that follow it start with the two {@code FY} digits, so {@link #regionOf} reads
 * the region back as the leading run of letters.
 */
public final class OwnerMemberId {

    /** Region sentinel used when neither the postcode nor the city resolves to a known region. */
    public static final String UNKNOWN_REGION = "UNKNOWN";

    private static final char SEPARATOR = '-';

    private OwnerMemberId() {
    }

    /** The {@code <REGION><FY><HASH8><CHK>} {@code memberId} for the owner's current fields. */
    public static String of(Owner owner) {
        String base = regionFor(owner) + FiscalYear.yy(owner.getRegistrationDate())
                + hash8(OwnerTelephone.toE164OrRaw(owner.getTelephone()) + owner.getLastName());
        return base + luhn(base);
    }

    /**
     * The owner's region for identity and display: the postcode/city region (see
     * {@link OwnerLocality#regionFor}), or {@link #UNKNOWN_REGION} when neither resolves.
     */
    public static String regionFor(Owner owner) {
        String region = OwnerLocality.regionFor(owner.getPostcode(), owner.getCity());
        return region != null ? region : UNKNOWN_REGION;
    }

    /**
     * A de-duplicated variant of {@code base}, formed by appending {@code -<n>} (e.g.
     * {@code NSW271A2B3C4D5} with {@code n == 2} becomes {@code NSW271A2B3C4D5-2}). Used when the
     * derived {@code memberId} collides with an existing owner's: the caller picks the smallest
     * {@code n} of 2 or more that is free. Keeping the suffix spelling here, next to {@link #of} and
     * {@link #regionOf}, keeps this class the single authority for the {@code memberId} format — the
     * {@code REGION} prefix is unchanged, so {@link #regionOf} still reads the region from the
     * leading letters.
     */
    public static String withSuffix(String base, int n) {
        return base + SEPARATOR + n;
    }

    /**
     * The {@code REGION} half of a {@code memberId} (the leading run of letters, before the first
     * {@code FY} digit), or {@code null} when {@code memberId} is null or carries no region prefix.
     */
    public static String regionOf(String memberId) {
        if (memberId == null) {
            return null;
        }
        int i = 0;
        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
            i++;
        }
        return i > 0 ? memberId.substring(0, i) : null;
    }

    /** The first 8 upper-case hex characters (4 bytes) of SHA-256 over {@code value}. */
    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** A single Luhn check digit (0-9) over the digits contained in {@code value}. */
    private static int luhn(String value) {
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}
===== OwnerSoundex =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Single source of truth for the Soundex encoding of an owner's last name used by the
 * {@code POST /owners} pipeline. The last name's Soundex code is folded into the owner
 * {@link OwnerIdentity identityKey} (so two owners whose surnames sound alike share that component
 * of the key) and is the basis for the soft-duplicate match in {@link AssignPossibleDuplicate}
 * (a request is a <em>possible</em> duplicate when its surname's Soundex and its postcode match an
 * existing owner's while its whole identity key differs).
 *
 * <p>Centralised here so the identity key and the soft-match cannot disagree about when two
 * surnames "sound the same".
 *
 * <p>Implements the standard American Soundex: keep the (upper-cased) first letter, encode the
 * remaining letters to the digits {@code BFPV=1 CGJKQSXZ=2 DT=3 L=4 MN=5 R=6} (vowels and
 * {@code HWY} map to no digit), collapse adjacent letters that share a code, treat {@code H}/{@code W}
 * as transparent (they do not separate two same-coded consonants) while a vowel does separate them,
 * then pad or truncate to a letter plus three digits. A value with no letters encodes to the empty
 * string.
 */
final class OwnerSoundex {

    private OwnerSoundex() {
    }

    /** The Soundex code of {@code value}, or the empty string when it contains no letters. */
    static String of(String value) {
        if (value == null) {
            return "";
        }
        StringBuilder letters = new StringBuilder();
        for (char c : value.toUpperCase(Locale.ROOT).toCharArray()) {
            if (c >= 'A' && c <= 'Z') {
                letters.append(c);
            }
        }
        if (letters.length() == 0) {
            return "";
        }
        StringBuilder code = new StringBuilder().append(letters.charAt(0));
        char previousCode = codeOf(letters.charAt(0));
        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
            char letter = letters.charAt(i);
            char digit = codeOf(letter);
            if (digit != '0' && digit != previousCode) {
                code.append(digit);
            }
            // H and W are transparent: they do not reset the running code, so two same-coded
            // consonants separated only by H/W still collapse. A vowel does reset it.
            if (letter != 'H' && letter != 'W') {
                previousCode = digit;
            }
        }
        while (code.length() < 4) {
            code.append('0');
        }
        return code.toString();
    }

    private static char codeOf(char c) {
        switch (c) {
            case 'B': case 'F': case 'P': case 'V':
                return '1';
            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
                return '2';
            case 'D': case 'T':
                return '3';
            case 'L':
                return '4';
            case 'M': case 'N':
                return '5';
            case 'R':
                return '6';
            default: // A E I O U H W Y
                return '0';
        }
    }
}
===== Sha256 =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Shared SHA-256 hex encoding for the {@code POST /owners} pipeline. Both the owner
 * {@link OwnerIdentity identityKey} (full, lower-case) and the {@link OwnerHousehold} household id
 * (first 12 characters, upper-cased) are the hex digest of a composed string; this centralises the
 * digest-and-encode mechanism so those callers choose only the case/length they want rather than
 * each re-implementing it.
 */
final class Sha256 {

    private static final char[] LOWER_HEX = "0123456789abcdef".toCharArray();

    private Sha256() {
    }

    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    static String hex(String value) {
        byte[] digest = digest(value);
        StringBuilder sb = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            sb.append(LOWER_HEX[(b >> 4) & 0xF]).append(LOWER_HEX[b & 0xF]);
        }
        return sb.toString();
    }

    private static byte[] digest(String value) {
        try {
            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Household assignment for {@code POST /owners}. The owner's {@code householdId} is
 * <em>deterministic</em>: it is derived from {@code (lastName, postcode)} alone (see
 * {@link OwnerHousehold#deriveId}), so every owner that shares a last name and postcode derives the
 * same id automatically — there is no longer any explicit linking of existing owners. Owners with
 * no postcode belong to no household and are left with a null {@code householdId}.
 *
 * <p>Runs within the create transaction (after {@link BuildOwner}/{@link AssignMemberId},
 * before {@link SaveOwner}). Sharing a household is no longer a duplicate: several members may
 * belong to the same household as long as their identity keys differ (see
 * {@link CheckOwnerIdentityUnique}). The id assigned here is purely a function of
 * {@code (lastName, postcode)} and is what {@link CapMembershipLevel} later uses to find the
 * household's existing members.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerHousehold.deriveId(owner));
    }
}
===== AssignMemberId =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code memberId}, the one unified identity formatted
 * {@code <REGION><FY><HASH8><CHK>} (e.g. {@code NSW271A2B3C4D5}). The format and its derivation live
 * in {@link OwnerMemberId}; this step just stores it on the owner.
 *
 * <p>The identity is deterministic from the owner's own fields alone — there is no per-city sequence
 * number, so it does not depend on how many owners already exist. It is the single identity every
 * derived owner value flows from: the create audit record and the read-time {@code locality} (and
 * through it the {@code ownerSegment}) all read it rather than recomputing region independently.
 *
 * <p>Runs after {@link BuildOwner} (which maps the normalised request onto the owner and defaults
 * and business-day-adjusts the {@code registrationDate}, so both the fiscal-year and hash inputs are
 * already set) and before {@link DeduplicateMemberId} and {@link SaveOwner}.
 */
public class AssignMemberId {

    public void service(@Val Owner owner) {
        owner.setMemberId(OwnerMemberId.of(owner));
    }
}
===== AuditOwnerCreated =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits the owner-created audit trail to the dedicated {@code AUDIT} logger once a new owner has
 * been persisted. Two things are emitted:
 * <ul>
 *   <li>a human-readable line recording the assigned owner id, the unified {@code memberId},
 *       {@code registrationDate} and the derived {@code membershipLevel};</li>
 *   <li>an immutable structured {@link OwnerCreatedEvent} (as JSON), tagged with a monotonically
 *       increasing {@link #SEQUENCE sequence} across creates and carrying the owner's current
 *       primary identifier.</li>
 * </ul>
 *
 * <p>Runs after {@link SaveOwner}, so the generated id is available.
 */
public class AuditOwnerCreated {

    private static final Logger logger = LoggerFactory.getLogger("AUDIT");

    /** Monotonically increasing sequence shared across all creates (and function instances). */
    private static final AtomicLong SEQUENCE = new AtomicLong();

    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
        int membershipLevel = ownerMapper.membershipLevel(owner);
        logger.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
                membershipLevel);

        // The owner's primary identifier is the unified memberId.
        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(),
                owner.getId(), owner.getMemberId(), membershipLevel);
        logger.info(event.toJson());
    }
}
===== OwnerCreatedEvent =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Immutable structured event emitted to the {@code AUDIT} logger when a new owner is created,
 * alongside the human-readable audit line (see {@link AuditOwnerCreated}). Serialised as the JSON
 * object {@code {seq, ownerId, memberId, membershipLevel, event}} with
 * {@code event == }{@value #EVENT}.
 *
 * <p>{@code seq} is a monotonically increasing sequence across creates (assigned by
 * {@link AuditOwnerCreated}), so consumers can order and de-duplicate events independently of log
 * timestamps.
 *
 * <p>The {@code memberId} field carries the owner's primary identifier: the unified
 * {@code memberId} ({@link OwnerMemberId}) — the record is the one place that definition lives.
 *
 * <p>Being a record, the event is deeply immutable once constructed.
 */
public record OwnerCreatedEvent(long seq, int ownerId, String memberId, int membershipLevel) {

    /** The {@code event} discriminator carried by every owner-created event. */
    public static final String EVENT = "OWNER_CREATED";

    /**
     * The canonical JSON form {@code {seq, ownerId, memberId, membershipLevel, event}}. Built
     * directly rather than via a mapper so the audit side-effect carries no dependency on the HTTP
     * response serialisation.
     */
    public String toJson() {
        return "{\"seq\":" + this.seq
                + ",\"ownerId\":" + this.ownerId
                + ",\"memberId\":" + quote(this.memberId)
                + ",\"membershipLevel\":" + this.membershipLevel
                + ",\"event\":\"" + EVENT + "\"}";
    }

    /** A JSON string literal for {@code value}, escaping the characters JSON requires, or {@code null}. */
    private static String quote(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"' -> sb.append("\\\"");
                case '\\' -> sb.append("\\\\");
                case '\n' -> sb.append("\\n");
                case '\r' -> sb.append("\\r");
                case '\t' -> sb.append("\\t");
                default -> {
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    }
                    else {
                        sb.append(c);
                    }
                }
            }
        }
        return sb.append('"').toString();
    }
}

